// Safely extract and truncate Groq document for Telegram (4096 char limit)
const content = $('Generate Document').item.json?.choices?.[0]?.message?.content || 'Помилка генерації документа. Зверніться до підтримки.';
const MAX = 3000;
const truncated = content.length > MAX
  ? content.slice(0, MAX) + '\n\n[Скорочено. Повна версія зберігається в системі.]'
  : content;
return [{ json: { _doc_text: '📄 Ваша позовна заява:\n\n' + truncated } }];
